    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ShrimpScript/porthole/releases/download/v0.43.0/portholed-linux-arm64"
      sha256 "d110023ce92c7b2f4062aeb1a9687d3fdc2190c6da9a23515e72cb3672b82f37"
